-- Produto enviado pelo Daniel: Desodorante Clareador 85ml (marca Rosa Selvagem)
-- Preço de TESTE R$ 1,00 e ativo para venda (preço definitivo depois da reunião com o contador). Impostos em branco.
INSERT INTO "brands" ("id", "name", "active", "sortOrder", "createdAt", "updatedAt")
VALUES (gen_random_uuid(), 'Rosa Selvagem', true, 11, now(), now())
ON CONFLICT ("name") DO NOTHING;

INSERT INTO "products" ("id", "sku", "name", "brandId", "description", "unit", "costCents", "taxRefBps", "priceCents",
                        "stockQty", "reservedQty", "active", "internalNotes", "createdAt", "updatedAt")
SELECT gen_random_uuid(), 'RSV-DESODORANTE-85', 'Desodorante Clareador 85ml', b."id",
       'Roll-on antitranspirante clareador • Proteção & Clareamento • Óleo de rosa selvagem, extrato de jabuticaba, óleo de melaleuca e ácidos de frutas (AHAs)',
       'UN', 0, 0, 100, 0, 0, true,
       'PREÇO DE TESTE (R$ 1,00). Definir o preço real após a reunião com o contador.', now(), now()
  FROM "brands" b WHERE b."name" = 'Rosa Selvagem'
ON CONFLICT ("sku") DO NOTHING;

INSERT INTO "stored_files" ("id", "area", "fileName", "mimeType", "sizeBytes", "data", "createdAt")
SELECT gen_random_uuid(), 'products', 'rosa-selvagem-desodorante-clareador-85.webp', 'image/webp', 35380, decode('', 'hex'), now()
WHERE NOT EXISTS (SELECT 1 FROM "stored_files" WHERE "fileName" = 'rosa-selvagem-desodorante-clareador-85.webp');
INSERT INTO "product_images" ("id", "productId", "fileName", "mimeType", "isPrimary", "sortOrder", "createdAt")
SELECT gen_random_uuid(), p."id", 'rosa-selvagem-desodorante-clareador-85.webp', 'image/webp', true, 0, now()
  FROM "products" p
 WHERE p."sku" = 'RSV-DESODORANTE-85' AND NOT EXISTS (SELECT 1 FROM "product_images" i WHERE i."productId" = p."id");
